import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import { useLastDataRefresh } from 'contexts';
import { useFilterAlertFallback } from 'hooks';
import { FilterForm } from 'models/Filters';
import { RootState } from 'redux/types';

import { PERFORMANCE_TOOL_PAGE_NAME } from '../../constants';
import {
  buildPeriodSignature,
  buildRestoreFilters,
  hasBreakdownDimensionsApplied,
  isInvalidMarketShareTimePeriod,
  isMarketShareKpi,
} from '../../utils/marketShareTimePeriodAlert.utils';

export const MARKET_SHARE_TIME_PERIOD_ALERT_KEY = 'market-share-time-period';

type AlertState = {
  hasInitialized: boolean;
  initialSignature: string | null;
  lastValidFilters: FilterForm | null;
  periodSignature: string | null;
  dismissed: boolean;
  previousValidPeriod: boolean;
};

const createAlertState = (): AlertState => ({
  hasInitialized: false,
  initialSignature: null,
  lastValidFilters: null,
  periodSignature: null,
  dismissed: false,
  previousValidPeriod: true,
});

const resetAlertTracking = (state: AlertState) => {
  state.periodSignature = null;
  state.dismissed = false;
  state.previousValidPeriod = true;
};

const maybeDismissFallback = (hasFallback: boolean, dismiss: () => void) => {
  if (hasFallback) {
    dismiss();
  }
};

const initializeSuppressInitialAlert = (
  state: AlertState,
  applied: FilterForm,
  appliedSignature: string,
  lastDataRefresh: Date | null | undefined,
) => {
  state.hasInitialized = true;
  state.initialSignature = appliedSignature;
  if (
    hasBreakdownDimensionsApplied(applied) &&
    !isInvalidMarketShareTimePeriod(applied, lastDataRefresh)
  ) {
    state.lastValidFilters = applied;
  }
};

const shouldSaveTimePeriodFallback = (
  signatureChanged: boolean,
  dismissed: boolean,
  hasExistingFallback: boolean,
) => signatureChanged && !dismissed && !hasExistingFallback;

export const useMarketShareTimePeriodAlert = (
  applied: FilterForm,
  enabled = true,
  suppressInitialAlert = false,
) => {
  const alertStateRef = useRef<AlertState>(createAlertState());
  const [isTimePeriodAlertOpen, setIsTimePeriodAlertOpen] = useState(false);

  const { lastDataRefreshKpisDate } = useLastDataRefresh();
  const lastDataRefresh = lastDataRefreshKpisDate?.market_share ?? null;

  const {
    fallback: marketShareTimePeriodFallback,
    saveFallback,
    dismissFallback,
  } = useFilterAlertFallback({
    pageName: PERFORMANCE_TOOL_PAGE_NAME,
    key: MARKET_SHARE_TIME_PERIOD_ALERT_KEY,
  });

  const pageDefaults = useSelector(
    (state: RootState) =>
      state.filters.pages[PERFORMANCE_TOOL_PAGE_NAME]?.defaults,
  );
  const restoreDefaults = useMemo(
    () => ({
      periods: pageDefaults?.periods,
      period_type: pageDefaults?.period_type,
      dt_end: pageDefaults?.dt_end,
    }),
    [pageDefaults?.dt_end, pageDefaults?.period_type, pageDefaults?.periods],
  );

  const closeTimePeriodAlert = useCallback(() => {
    alertStateRef.current.dismissed = true;
    setIsTimePeriodAlertOpen(false);
  }, []);

  useEffect(() => {
    const closeAlertAndReset = () => {
      setIsTimePeriodAlertOpen(false);
      resetAlertTracking(alertStateRef.current);
      maybeDismissFallback(
        Boolean(marketShareTimePeriodFallback),
        dismissFallback,
      );
    };

    if (!enabled || !isMarketShareKpi(applied.kpis)) {
      closeAlertAndReset();
      return;
    }

    const appliedSignature = JSON.stringify(applied);
    const state = alertStateRef.current;

    if (suppressInitialAlert) {
      if (!state.hasInitialized) {
        initializeSuppressInitialAlert(
          state,
          applied,
          appliedSignature,
          lastDataRefresh,
        );
        closeAlertAndReset();
        return;
      }

      if (state.initialSignature === appliedSignature) {
        setIsTimePeriodAlertOpen(false);
        return;
      }
    }

    if (!hasBreakdownDimensionsApplied(applied)) {
      closeAlertAndReset();
      return;
    }

    const periodSignature = buildPeriodSignature(applied);
    const signatureChanged = state.periodSignature !== periodSignature;
    if (signatureChanged) {
      state.periodSignature = periodSignature;
      state.dismissed = false;
    }

    const invalidPeriod = isInvalidMarketShareTimePeriod(
      applied,
      lastDataRefresh,
    );

    if (!invalidPeriod) {
      state.lastValidFilters = applied;
      setIsTimePeriodAlertOpen(false);
      maybeDismissFallback(
        Boolean(marketShareTimePeriodFallback),
        dismissFallback,
      );
      return;
    }

    state.previousValidPeriod = false;
    if (
      shouldSaveTimePeriodFallback(
        signatureChanged,
        state.dismissed,
        Boolean(marketShareTimePeriodFallback),
      )
    ) {
      const restoreFilters = buildRestoreFilters(
        applied,
        restoreDefaults,
        state.lastValidFilters,
      );
      saveFallback({
        previousFilters: restoreFilters,
        lastValidFilters: state.lastValidFilters ?? undefined,
        targetKpi: String(applied.kpis ?? ''),
        restoreStrategy: state.lastValidFilters
          ? 'last-valid-filters'
          : 'page-defaults',
      });
    }

    setIsTimePeriodAlertOpen(!state.dismissed);
  }, [
    applied,
    dismissFallback,
    enabled,
    lastDataRefresh,
    marketShareTimePeriodFallback,
    restoreDefaults,
    saveFallback,
    suppressInitialAlert,
  ]);

  return { isTimePeriodAlertOpen, closeTimePeriodAlert };
};
